CREATE TYPE public.app_role AS ENUM ('creator');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE TABLE public.account_access (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, username text NOT NULL UNIQUE, blocked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT username_format CHECK(username ~ '^[a-z0-9][a-z0-9._-]{2,39}$'));
GRANT SELECT ON public.account_access TO authenticated;
GRANT ALL ON public.account_access TO service_role;
ALTER TABLE public.account_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_access ON public.account_access FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.account_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.account_access WHERE user_id = auth.uid() AND blocked) $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT _user_id = auth.uid() AND public.account_active() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.account_active() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.account_active(), public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.is_member(_center uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.account_active() AND EXISTS(SELECT 1 FROM public.center_memberships WHERE center_id = _center AND user_id = auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.has_center_role(_center uuid, _roles public.center_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.account_active() AND EXISTS(SELECT 1 FROM public.center_memberships WHERE center_id = _center AND user_id = auth.uid() AND role = ANY(_roles)) $$;
REVOKE EXECUTE ON FUNCTION public.create_center(text,text,text,text,text,boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_center(text,text,text,text,text,boolean) TO service_role;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','centers','center_memberships','subscriptions','courses','teachers','groups','students','enrollments','class_sessions','attendance_records','payments','expenses','financial_adjustments','notifications','audit_logs'] LOOP EXECUTE format('CREATE POLICY active_account ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.account_active()) WITH CHECK (public.account_active())', t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF coalesce(new.raw_app_meta_data->>'admin_provisioned','false') <> 'true' THEN RAISE EXCEPTION 'Hisobni administrator yaratishi kerak'; END IF; INSERT INTO public.profiles(id,full_name,phone) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.raw_user_meta_data->>'phone') ON CONFLICT(id) DO NOTHING; RETURN new; END $$;
CREATE TABLE public.creator_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, action text NOT NULL, target_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.creator_audit TO authenticated;
GRANT ALL ON public.creator_audit TO service_role;
ALTER TABLE public.creator_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY creator_reads_audit ON public.creator_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'creator'));
CREATE OR REPLACE FUNCTION public.creator_create_center(_name text, _phone text, _city text, _owner uuid) RETURNS uuid LANGUAGE plpgsql SET search_path = public AS $$ DECLARE cid uuid; BEGIN INSERT INTO public.centers(name,phone,city,owner_id) VALUES(_name,_phone,_city,_owner) RETURNING id INTO cid; INSERT INTO public.center_memberships(center_id,user_id,role) VALUES(cid,_owner,'owner'); INSERT INTO public.subscriptions(center_id,plan) VALUES(cid,'start'); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.creator_create_center(text,text,text,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.creator_create_center(text,text,text,uuid) TO service_role;